// Demo: Signature Copula-Based Tabular Synthesis — distribution match check (KS-style)
function cdf(samples,x){var c=0;samples.forEach(function(s){if(s<=x)c++;});return c/samples.length;}
var real=[],synth=[];for(var i=0;i<2;i++){real.push(50+10*Math.sin(i/7)+((i*1)%9));synth.push(50+10*Math.sin(i/7)+((i*(1+3))%9));}
var ks=0;[40,50,60,70].forEach(function(x){ks=Math.max(ks,Math.abs(cdf(real,x)-cdf(synth,x)));});
console.log('technique: Signature Copula-Based Tabular Synthesis');console.log('max CDF gap (KS-style): '+ks.toFixed(3));
console.log(ks<0.15?'result: synthetic distribution matches real data':'result: distributions diverge — retrain the generator');

