// Demo: Signature Differentially Private Synthesis — privacy check: nearest-real-record distance
function dist(a,b){return Math.abs(a.x-b.x)+Math.abs(a.y-b.y);}
var real=[];for(var i=0;i<28;i++){real.push({x:(i*37)%100,y:(i*53)%100});}
var synth={x:17%100,y:63%100};var best=1e9;
real.forEach(function(r){best=Math.min(best,dist(r,synth));});
console.log('technique: Signature Differentially Private Synthesis');console.log('nearest real record distance: '+best);
console.log(best>0?'result: no exact copy of a real record':'result: WARNING — synthetic row copies a real record');

// Demo: Signature SMOTE Oversampling — synthetic value sampler
function mulberry(seed){var a=seed>>>0;return function(){a|=0;a=(a+0x6D2B79F5)|0;var t=Math.imul(a^(a>>>15),1|a);t=(t+Math.imul(t^(t>>>7),61|t))^t;return((t^(t>>>14))>>>0)/4294967296;};}
var rnd=mulberry(4);var rows=[];
for(var i=0;i<22;i++){rows.push({age:18+Math.floor(rnd()*60),score:Math.round(rnd()*1000)/10});}
var mean=rows.reduce(function(a,r){return a+r.score;},0)/rows.length;
console.log('technique: Signature SMOTE Oversampling');console.log('synthetic rows: '+rows.length);
console.log('mean score: '+mean.toFixed(1)+', age range: '+Math.min.apply(null,rows.map(function(r){return r.age;}))+'-'+Math.max.apply(null,rows.map(function(r){return r.age;})));
console.log('first row: '+JSON.stringify(rows[0]));

